func:
// Routes the monitor page, status JSON, history request or an unknown path.
// In: an authenticated GET with an optional query parameter `view`.
// Out: exactly one of PAGE, STATUS, HISTORY or ERROR.
var query = msg.req && msg.req.query ? msg.req.query : {};
var view = query.view;

if (view === undefined || view === '' || view === 'page') {
  return [msg, null, null, null];
}
if (view === 'status') {
  return [null, msg, null, null];
}
if (view === 'history') {
  return [null, null, msg, null];
}

msg.statusCode = 404;
msg.headers = {
  'content-type': 'application/json'
};
msg.payload = {
  error: 'unknown monitor endpoint'
};
return [null, null, null, msg];

// Builds a JSON snapshot of the small global run-status records.
// In: an authenticated status request.
// Out: JSON with a derived STUCK state after 30 minutes without a checkpoint.
var STUCK_AFTER_MS = 30 * 60 * 1000;
var now = Date.now();
var keys = [
  'runStatus_sih-hull',
  'runStatus_rpt-hull',
  'runStatus_pbi-report',
  'runStatus_pbi-listener'
];
var flows = {};

function active(status) {
  if (status.state === 'running' || status.state === 'queued') {
    return true;
  }
  var days = status.days || {};
  return Object.keys(days).some(function (day) {
    return days[day].state === 'running' ||
      days[day].state === 'queued';
  });
}

function snapshot(key) {
  var stored = glob.get(key);
  if (!stored || typeof stored !== 'object') {
    return {
      state: 'not started'
    };
  }

  var copy = JSON.parse(JSON.stringify(stored));
  var running = active(copy);
  copy.state = copy.state || (running ? 'running' : 'idle');
  var beat = Date.parse(copy.lastBeatAt || copy.startedAt || '');
  if (running && isFinite(beat) && now - beat > STUCK_AFTER_MS) {
    copy.state = 'STUCK';
    copy.stuck = true;
    Object.keys(copy.days || {}).forEach(function (day) {
      var item = copy.days[day];
      if (item.state === 'running' || item.state === 'queued') {
        item.state = 'STUCK';
      }
    });
  } else {
    copy.stuck = false;
  }
  return copy;
}

keys.forEach(function (key) {
  flows[key.replace('runStatus_', '')] = snapshot(key);
});
var cfg = glob.get('cfg');
flows.config = cfg && cfg.platform && Array.isArray(cfg.sites) ?
  {
    state: 'ready',
    platform: cfg.platform,
    sites: cfg.sites.length
  } : {
    state: 'unavailable'
  };

msg.statusCode = 200;
msg.headers = {
  'content-type': 'application/json; charset=utf-8',
  'cache-control': 'no-store'
};
msg.payload = {
  generatedAt: new Date(now).toISOString(),
  stuckAfterMs: STUCK_AFTER_MS,
  flows: flows,
  commands: glob.get('runMonitorCommands') || []
};
return msg;

// Validates a history query and builds the one-month data-lake folder path.
// In: query.flow and query.month from the authenticated history request.
// Out: the list-objects request, or an explicit 400/503 JSON response.
var FLOWS = [
  'sih-hull',
  'rpt-hull',
  'pbi-report',
  'run-monitor'
];
var query = msg.req && msg.req.query ? msg.req.query : {};
var flowName = String(query.flow || '');
var month = String(query.month || '');

function refuse(code, reason) {
  msg.statusCode = code;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: reason
  };
  return [null, msg];
}

if (FLOWS.indexOf(flowName) === -1) {
  return refuse(400, 'flow must be a known report log');
}
if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) {
  return refuse(400, 'month must be YYYY-MM');
}

var cfg = glob.get('cfg');
if (!cfg || !cfg.root) {
  return refuse(503, 'Config is not available');
}

msg.historyFlow = flowName;
msg.historyMonth = month;
msg.historyFolder = cfg.root + '/logs/' + flowName + '/';
msg.historyName = 'log_' + month + '.csv';
msg.path = msg.historyFolder;
return [msg, null];

// Finds the requested month file in the listed log folder.
// In: msg.payload = list objects result; msg.historyName = exact filename.
// Out: read object (path without data/ten=<tenant>/), 404 when absent, or
// 502 for an invalid list response.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
if (!Array.isArray(msg.payload)) {
  msg.statusCode = 502;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'the data lake did not return a history folder list'
  };
  return [null, null, msg];
}

var found = msg.payload.filter(function (item) {
  return String(item.key || '').split('/').pop() === msg.historyName;
})[0];

if (!found) {
  msg.statusCode = 404;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'history file not found',
    flow: msg.historyFlow,
    month: msg.historyMonth
  };
  return [null, msg, null];
}

msg.path = String(found.key).replace(TENANT_PREFIX, '');
return [msg, null, null];

// Parses one quoted CSV log file and returns its newest 200 rows as JSON.
// In: msg.payload = the CSV text from the data lake read-object node.
// Out: JSON rows, or an explicit 502 for an unusable file.
var MAX_ROWS = 200;

// The read node gives a Buffer (or a serialised one) in the VFC, or text.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (Buffer.isBuffer(payload)) {
    return payload.toString('utf8');
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    return Buffer.from(payload.data).toString('utf8');
  }
  return null;
}

var text = decode(msg.payload);
if (text === null) {
  msg.statusCode = 502;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'the data lake did not return log text'
  };
  return msg;
}

var rows = [];
var row = [];
var field = '';
var quoted = false;
for (var i = 0; i < text.length; i++) {
  var ch = text.charAt(i);
  if (ch === '"') {
    if (quoted && text.charAt(i + 1) === '"') {
      field += '"';
      i++;
    } else {
      quoted = !quoted;
    }
  } else if (ch === ',' && !quoted) {
    row.push(field);
    field = '';
  } else if (ch === '\n' && !quoted) {
    row.push(field.replace(/\r$/, ''));
    rows.push(row);
    row = [];
    field = '';
  } else {
    field += ch;
  }
}
if (field || row.length) {
  row.push(field.replace(/\r$/, ''));
  rows.push(row);
}

var headers = rows.shift() || [];
if (headers.indexOf('ts_utc') === -1 ||
    headers.indexOf('message') === -1) {
  msg.statusCode = 502;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'the history file has an unexpected header'
  };
  return msg;
}

var entries = rows.filter(function (values) {
  return values.some(function (value) {
    return value !== '';
  });
}).map(function (values) {
  var entry = {};
  headers.forEach(function (header, index) {
    entry[header] = values[index] || '';
  });
  return entry;
});
var total = entries.length;
var recent = entries.slice(-MAX_ROWS);

msg.statusCode = 200;
msg.headers = {
  'content-type': 'application/json; charset=utf-8',
  'cache-control': 'no-store'
};
msg.payload = {
  flow: msg.historyFlow,
  month: msg.historyMonth,
  count: total,
  truncated: total - recent.length,
  rows: recent
};
return msg;

// Validates a backfill command, records its audit entry and emits one target.
// In: JSON {flow, force, start/end} or {flow, force, from/to, tables, sites}.
// Out: HTTP 202/400/409/503, one BACKFILL message, and a CSV log message.
var DAILY_FLOWS = ['sih-hull', 'rpt-hull'];
var PBI_TABLES = [
  'Plan_OPT_EU',
  'Time_Utilisation_EU',
  'Daily_Losses_EU'
];
var MAX_DAYS = 31;
var MAX_MONTHS = 12;

// The VFC http in node can hand the POST body over as an object, as JSON
// text, as a Buffer (also serialised) or in msg.req.body: take all of them.
function parseBody(value) {
  var text = null;
  if (typeof value === 'string') {
    text = value;
  } else if (Buffer.isBuffer(value)) {
    text = value.toString('utf8');
  } else if (value && value.type === 'Buffer' && value.data) {
    text = Buffer.from(value.data).toString('utf8');
  } else {
    return value;
  }
  try {
    return JSON.parse(text);
  } catch (e) {
    return undefined;
  }
}

function describe(value) {
  if (value === undefined || value === null) {
    return 'nothing';
  }
  return Buffer.isBuffer(value) ? 'a Buffer' : typeof value;
}

var request = parseBody(msg.payload);
var gotBody = describe(msg.payload);
if (!request || typeof request !== 'object') {
  request = parseBody(msg.req && msg.req.body);
  gotBody += ', req.body ' + describe(msg.req && msg.req.body);
}
var acceptedFlow = '';
var force = !!(request && request.force === true);
var cfg = glob.get('cfg');

function audit(result, flowName, range, forced, detail) {
  var events = glob.get('runMonitorCommands') || [];
  var entry = {
    at: new Date().toISOString(),
    flow: flowName,
    result: result,
    force: forced,
    range: range,
    detail: detail
  };
  events.push(entry);
  if (events.length > 50) {
    events.splice(0, events.length - 50);
  }
  glob.set('runMonitorCommands', events);

  if (!cfg || !cfg.root) {
    return null;
  }
  flow.set('cfg', {
    root: cfg.root
  });
  return {
    payload: '[command] ' + result.toUpperCase() + ': ' + flowName +
      (range ? ' ' + range : '') + (forced ? ' force=true' : ''),
    level: result === 'accepted' ? 'info' : 'warn',
    source: 'run-monitor'
  };
}

function response(status, body) {
  var out = Object.assign({}, msg);
  out.statusCode = status;
  out.headers = {
    'content-type': 'application/json; charset=utf-8',
    'cache-control': 'no-store'
  };
  out.payload = body;
  return out;
}

function refuse(status, reason, flowName, range) {
  var name = flowName || 'unknown';
  var log = audit('rejected', name, range || '', force, reason);
  return [
    response(status, {
      accepted: false,
      error: reason
    }),
    null,
    null,
    null,
    log
  ];
}

function validDay(value) {
  if (typeof value !== 'string' ||
      !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return null;
  }
  var parts = value.split('-').map(Number);
  var date = new Date(0);
  date.setUTCFullYear(parts[0], parts[1] - 1, parts[2]);
  date.setUTCHours(0, 0, 0, 0);
  if (date.getUTCFullYear() !== parts[0] ||
      date.getUTCMonth() !== parts[1] - 1 ||
      date.getUTCDate() !== parts[2]) {
    return null;
  }
  return date.getTime();
}

function monthIndex(value) {
  if (typeof value !== 'string' ||
      !/^\d{4}-(0[1-9]|1[0-2])$/.test(value)) {
    return null;
  }
  return Number(value.slice(0, 4)) * 12 +
    Number(value.slice(5, 7)) - 1;
}

function busy(flowName) {
  if (flowName === 'pbi-report' &&
      (glob.get('jobQueue') || []).length > 0) {
    return true;
  }
  var status = glob.get('runStatus_' + flowName);
  if (!status) {
    return false;
  }
  if (status.state === 'running' || status.state === 'queued') {
    return true;
  }
  return Object.keys(status.days || {}).some(function (day) {
    return status.days[day].state === 'running' ||
      status.days[day].state === 'queued';
  });
}

if (!request || typeof request !== 'object' || Array.isArray(request)) {
  return refuse(
    400,
    'payload must be a JSON object (got ' + gotBody + ')',
    '',
    ''
  );
}
if (request.force !== undefined && typeof request.force !== 'boolean') {
  return refuse(400, 'force must be a boolean', '', '');
}
var flowName = String(request.flow || '');
if (DAILY_FLOWS.indexOf(flowName) === -1 &&
    flowName !== 'pbi-report') {
  return refuse(400, 'flow must be a known report flow', '', '');
}
acceptedFlow = flowName;

if (!cfg || !cfg.root || !Array.isArray(cfg.sites)) {
  return refuse(503, 'Config is not available', acceptedFlow, '');
}

var range = '';
var dailyPayload = null;
var pbiPayload = null;
if (DAILY_FLOWS.indexOf(flowName) !== -1) {
  var startMs = validDay(request.start);
  var endMs = validDay(request.end);
  if (startMs === null || endMs === null || endMs < startMs) {
    return refuse(
      400,
      'start and end must be valid YYYY-MM-DD dates, start not after end',
      flowName,
      ''
    );
  }
  var days = Math.floor((endMs - startMs) / 86400000) + 1;
  if (days > MAX_DAYS) {
    return refuse(
      400,
      'date range must not exceed ' + MAX_DAYS + ' days',
      flowName,
      ''
    );
  }
  range = request.start + '..' + request.end;
  dailyPayload = {
    start: request.start,
    end: request.end
  };
} else {
  var fromIndex = monthIndex(request.from);
  var toIndex = monthIndex(request.to);
  if (fromIndex === null || toIndex === null || toIndex < fromIndex) {
    return refuse(
      400,
      'from and to must be valid YYYY-MM months, from not after to',
      flowName,
      ''
    );
  }
  var months = toIndex - fromIndex + 1;
  if (months > MAX_MONTHS) {
    return refuse(
      400,
      'month range must not exceed ' + MAX_MONTHS + ' months',
      flowName,
      ''
    );
  }
  var sites = cfg.sites.map(function (site) {
    return site.name;
  });
  pbiPayload = {
    from: request.from,
    to: request.to
  };
  if (request.tables !== undefined) {
    if (!Array.isArray(request.tables) || !request.tables.length ||
        request.tables.some(function (table) {
          return PBI_TABLES.indexOf(table) === -1;
        })) {
      return refuse(400, 'tables must be known PBI report tables', flowName,
        '');
    }
    pbiPayload.tables = request.tables.slice();
  }
  if (request.sites !== undefined) {
    if (!Array.isArray(request.sites) || !request.sites.length ||
        request.sites.some(function (site) {
          return sites.indexOf(site) === -1;
        })) {
      return refuse(400, 'sites must be present in Config', flowName, '');
    }
    pbiPayload.sites = request.sites.slice();
  }
  range = request.from + '..' + request.to;
}

if (busy(flowName) && !force) {
  return refuse(
    409,
    'flow is busy; set force=true to allow a concurrent backfill',
    flowName,
    range
  );
}

var now = new Date().toISOString();
if (dailyPayload) {
  var current = glob.get('runStatus_' + flowName) || {
    flow: flowName
  };
  current.state = 'queued';
  current.mode = 'backfill';
  current.runId = 'monitor-' + Date.now().toString(36);
  current.startedAt = now;
  current.lastBeatAt = now;
  current.days = {};
  glob.set('runStatus_' + flowName, current);
} else {
  var tableSummary = (pbiPayload.tables || ['all']).join(', ').slice(0, 120);
  var siteSummary = (pbiPayload.sites || ['all']).join(', ').slice(0, 120);
  glob.set('runStatus_pbi-report', {
    flow: 'pbi-report',
    state: 'queued',
    source: 'monitor',
    startedAt: now,
    lastBeatAt: now,
    job: {
      tables: tableSummary,
      sites: siteSummary,
      from: pbiPayload.from,
      to: pbiPayload.to
    },
    lastLog: ''
  });
}

var log = audit('accepted', flowName, range, force, '');
var result = response(202, {
  accepted: true,
  flow: flowName,
  range: range,
  forced: force
});
if (flowName === 'sih-hull') {
  return [
    result,
    {
      payload: dailyPayload
    },
    null,
    null,
    log
  ];
}
if (flowName === 'rpt-hull') {
  return [
    result,
    null,
    {
      payload: dailyPayload
    },
    null,
    log
  ];
}
return [
  result,
  null,
  null,
  {
    payload: pbiPayload
  },
  log
];

// Returns a safe, explicit error for monitor-node failures.
// In: a message from a catch node.
// Out: a generic JSON 502 without exposing request credentials.
node.status({
  fill: 'red',
  shape: 'ring',
  text: 'monitor request failed'
});
msg.statusCode = 502;
msg.headers = {
  'content-type': 'application/json'
};
msg.payload = {
  error: 'monitor request failed'
};
return msg;

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'run-monitor';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'run-monitor';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
